import { useEffect, useState } from 'react';

function Checkout() {
  const params = new URLSearchParams(window.location.search);
  const orderId = params.get('order_id');

  const [order, setOrder] = useState(null);
  const [method, setMethod] = useState(null);
  const [vpa, setVpa] = useState('');
  const [card, setCard] = useState({
    number: '',
    expiry: '',
    cvv: '',
    name: ''
  });
  const [paymentId, setPaymentId] = useState(null);
  const [status, setStatus] = useState('idle');

  useEffect(() => {
    if (!orderId) return;

    fetch(`http://localhost:8000/api/v1/orders/${orderId}/public`)
      .then(res => res.json())
      .then(data => setOrder(data))
      .catch(() => setStatus('failed'));
  }, [orderId]);

  useEffect(() => {
    if (!paymentId) return;

    const interval = setInterval(() => {
      fetch(`http://localhost:8000/api/v1/payments/${paymentId}/public`)
        .then(res => res.json())
        .then(data => {
          if (data.status === 'success' || data.status === 'failed') {
            setStatus(data.status);
            clearInterval(interval);
          }
        });
    }, 2000);

    return () => clearInterval(interval);
  }, [paymentId]);

  const handlePayment = (e) => {
    e.preventDefault();
    setStatus('processing');

    const payload = { order_id: orderId, method };

    if (method === 'upi') payload.vpa = vpa;

    if (method === 'card') {
      const [month, year] = card.expiry.split('/');
      payload.card = {
        number: card.number,
        expiry_month: month,
        expiry_year: year,
        cvv: card.cvv,
        holder_name: card.name
      };
    }

    fetch('http://localhost:8000/api/v1/payments/public', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    })
      .then(res => res.json())
      .then(data => setPaymentId(data.id))
      .catch(() => setStatus('failed'));
  };

  if (!orderId) {
    return (
      <div style={styles.centerText}>
        Please open checkout with a valid order link.
      </div>
    );
  }

  if (!order) {
    return <div style={styles.centerText}>Loading...</div>;
  }

  return (
    <div data-test-id="checkout-container" style={styles.container}>

      {/* Order Summary */}
      <div data-test-id="order-summary" style={styles.card}>
        <h2 style={styles.title}>Complete Payment</h2>
        <p>
          Amount:
          <span data-test-id="order-amount" style={styles.bold}>
            ₹{(order.amount / 100).toFixed(2)}
          </span>
        </p>
        <p>
          Order ID:
          <span data-test-id="order-id" style={styles.bold}>
            {order.id}
          </span>
        </p>
      </div>

      {/* Payment Methods */}
      {status === 'idle' && (
        <div data-test-id="payment-methods" style={styles.buttonGroup}>
          <button
            data-test-id="method-upi"
            style={styles.primaryButton}
            onClick={() => setMethod('upi')}
          >
            Pay with UPI
          </button>

          <button
            data-test-id="method-card"
            style={styles.secondaryButton}
            onClick={() => setMethod('card')}
          >
            Pay with Card
          </button>
        </div>
      )}

      {/* UPI Form */}
      {method === 'upi' && status === 'idle' && (
        <form data-test-id="upi-form" onSubmit={handlePayment} style={styles.form}>
          <input
            data-test-id="vpa-input"
            placeholder="username@bank"
            value={vpa}
            onChange={e => setVpa(e.target.value)}
            style={styles.input}
          />
          <button data-test-id="pay-button" style={styles.successButton}>
            Pay ₹{(order.amount / 100).toFixed(0)}
          </button>
        </form>
      )}

      {/* Card Form */}
      {method === 'card' && status === 'idle' && (
        <form data-test-id="card-form" onSubmit={handlePayment} style={styles.form}>
          <input data-test-id="card-number-input" placeholder="Card Number"
            style={styles.input}
            value={card.number}
            onChange={e => setCard({ ...card, number: e.target.value })}
          />
          <input data-test-id="expiry-input" placeholder="MM/YY"
            style={styles.input}
            value={card.expiry}
            onChange={e => setCard({ ...card, expiry: e.target.value })}
          />
          <input data-test-id="cvv-input" placeholder="CVV"
            style={styles.input}
            value={card.cvv}
            onChange={e => setCard({ ...card, cvv: e.target.value })}
          />
          <input data-test-id="cardholder-name-input" placeholder="Name on Card"
            style={styles.input}
            value={card.name}
            onChange={e => setCard({ ...card, name: e.target.value })}
          />
          <button data-test-id="pay-button" style={styles.successButton}>
            Pay ₹{(order.amount / 100).toFixed(0)}
          </button>
        </form>
      )}

      {status === 'processing' && (
        <div data-test-id="processing-state" style={styles.centerText}>
          <span data-test-id="processing-message">Processing payment...</span>
        </div>
      )}

      {status === 'success' && (
        <div data-test-id="success-state" style={styles.successText}>
          <h2>Payment Successful!</h2>
          <p>Payment ID: <span data-test-id="payment-id">{paymentId}</span></p>
          <span data-test-id="success-message">
            Your payment has been processed successfully
          </span>
        </div>
      )}

      {status === 'failed' && (
        <div data-test-id="error-state" style={styles.errorText}>
          <h2>Payment Failed</h2>
          <span data-test-id="error-message">
            Payment could not be processed
          </span>
          <button
            data-test-id="retry-button"
            style={styles.dangerButton}
            onClick={() => window.location.reload()}
          >
            Try Again
          </button>
        </div>
      )}

    </div>
  );
}

/* ✅ STYLES ONLY */
const styles = {
  container: {
    maxWidth: '420px',
    margin: '60px auto',
    padding: '24px',
    fontFamily: 'Inter, Arial, sans-serif'
  },
  card: {
    background: '#ffffff',
    padding: '20px',
    borderRadius: '10px',
    boxShadow: '0 10px 20px rgba(0,0,0,0.08)',
    marginBottom: '20px'
  },
  title: { marginBottom: '12px' },
  bold: { fontWeight: 600, marginLeft: '6px' },
  buttonGroup: { display: 'flex', gap: '10px' },
  primaryButton: {
    flex: 1, padding: '12px', background: '#2563eb',
    color: '#fff', border: 'none', borderRadius: '8px', cursor: 'pointer'
  },
  secondaryButton: {
    flex: 1, padding: '12px', background: '#fff',
    color: '#2563eb', border: '1px solid #2563eb',
    borderRadius: '8px', cursor: 'pointer'
  },
  form: { marginTop: '16px' },
  input: {
    width: '100%', padding: '10px',
    marginBottom: '10px', borderRadius: '6px',
    border: '1px solid #d1d5db'
  },
  successButton: {
    width: '100%', padding: '12px',
    background: '#16a34a', color: '#fff',
    border: 'none', borderRadius: '8px', cursor: 'pointer'
  },
  dangerButton: {
    marginTop: '12px', padding: '10px 16px',
    background: '#dc2626', color: '#fff',
    border: 'none', borderRadius: '6px', cursor: 'pointer'
  },
  centerText: { textAlign: 'center', marginTop: '40px' },
  successText: { textAlign: 'center', color: '#16a34a', marginTop: '20px' },
  errorText: { textAlign: 'center', color: '#dc2626', marginTop: '20px' }
};

export default Checkout;
